SET ROLE talus_fn;
CREATE TABLE app.communication_template(tenant_id uuid NOT NULL,communication_template_id uuid NOT NULL,event_type text NOT NULL,channel text NOT NULL CHECK(channel IN('sms','email')),subject_template text,body_template text NOT NULL,is_active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,communication_template_id),UNIQUE(tenant_id,event_type,channel));
CREATE TABLE app.communication_outbox(tenant_id uuid NOT NULL,communication_outbox_id uuid NOT NULL,recipient_customer_id uuid,channel text NOT NULL CHECK(channel IN('sms','email')),destination text NOT NULL,rendered_subject text,rendered_body text NOT NULL,context_payload jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL CHECK(status IN('queued','processing','sent','failed','delivered')),provider_message_ref text,retry_count integer NOT NULL DEFAULT 0,send_after timestamptz NOT NULL DEFAULT clock_timestamp(),sent_at timestamptz,error_message text,PRIMARY KEY(tenant_id,communication_outbox_id),FOREIGN KEY(tenant_id,recipient_customer_id) REFERENCES app.customer(tenant_id,customer_id));
CREATE OR REPLACE FUNCTION app.m11_outbox_final() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status IN('sent','delivered') AND (NEW.rendered_subject IS DISTINCT FROM OLD.rendered_subject OR NEW.rendered_body IS DISTINCT FROM OLD.rendered_body OR TG_OP='DELETE') THEN RAISE EXCEPTION 'FINALIZED_MESSAGE_IMMUTABLE' USING ERRCODE='55000';END IF;RETURN NEW;END;$$;
CREATE TRIGGER m11_outbox_final BEFORE UPDATE OR DELETE ON app.communication_outbox FOR EACH ROW EXECUTE FUNCTION app.m11_outbox_final();
CREATE OR REPLACE FUNCTION app.enqueue_notification(p_id uuid,p_customer uuid,p_event text,p_channel text,p_destination text,p_subject text,p_body text,p_context jsonb DEFAULT '{}'::jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();BEGIN PERFORM app.require_context();INSERT INTO app.communication_outbox VALUES(t,p_id,p_customer,p_channel,p_destination,p_subject,p_body,p_context,'queued',NULL,0,clock_timestamp(),NULL,NULL);PERFORM app.append_audit('communication.enqueued','communication_outbox',p_id);RETURN p_id;END;$$;
CREATE OR REPLACE FUNCTION app.record_delivery_attempt(p_id uuid,p_status text,p_ref text,p_error text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();BEGIN PERFORM app.require_context('worker');UPDATE app.communication_outbox SET status=p_status,provider_message_ref=p_ref,retry_count=retry_count+1,sent_at=CASE WHEN p_status IN('sent','delivered') THEN clock_timestamp() ELSE sent_at END,error_message=p_error WHERE tenant_id=t AND communication_outbox_id=p_id AND status NOT IN('sent','delivered');IF NOT FOUND THEN RAISE EXCEPTION 'OUTBOX_NOT_MUTABLE' USING ERRCODE='P0001';END IF;PERFORM app.append_audit('communication.delivery_recorded','communication_outbox',p_id);RETURN p_id;END;$$;
DO $$ DECLARE x text;BEGIN FOREACH x IN ARRAY ARRAY['communication_template','communication_outbox'] LOOP EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY;ALTER TABLE app.%I FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_context_policy ON app.%I USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid())',x,x,x);END LOOP;END;$$;
REVOKE ALL ON app.communication_template,app.communication_outbox FROM PUBLIC,talus_staff,talus_api,talus_customer;
RESET ROLE;
